const test = require('node:test');
const assert = require('node:assert/strict');
const { manifest } = require('../workshops/service.cjs');
const { validateCodes } = require('../workshops/validate.cjs');
test('duplicate identity is defined after normalization', () => {
  for (const codes of [[' ux-7 ','UX-7'],['AI2',' ai2 '],['net','NET'],['a','a']]) {
    assert.throws(() => manifest(codes), /duplicate workshop code/);
  }
  const input = Object.freeze([' ux-7 ','AI2',' net-8']);
  assert.equal(manifest(input),'UX-7\nAI2\nNET-8\n');
  assert.deepEqual(validateCodes(input),['UX-7','AI2','NET-8']);
  assert.equal(manifest([]),'');
  assert.equal(manifest(['a','a-1']),'A\nA-1\n');
  assert.equal(manifest(['only']),'ONLY\n');
});

