const { canonicalCode } = require('./normalize.cjs');
function validateCodes(codes) {
  const seen = new Set();
  return codes.map(code => {
    const normalized = canonicalCode(code);
    if (seen.has(normalized)) throw new Error('duplicate workshop code');
    seen.add(normalized);
    return normalized;
  });
}
module.exports = { validateCodes };
